"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["8071"],{65523(e){e.exports=JSON.parse('{"id":"FIN-187","slug":"free-cash-flow-to-equity","term":"Free Cash Flow to Equity (FCFE)","also_known_as":["FCFE","Levered Free Cash Flow"],"difficulty":"Intermediate","definition":"Free cash flow to equity (FCFE) is the cash available to a company\'s shareholders after operating costs, taxes, reinvestment and all payments to and from lenders.","explanation":["FCFE starts with the cash the business generates and then accounts for debt. It subtracts interest and debt repayments and adds any new borrowing. What remains could, in principle, be paid out to shareholders as dividends or share buybacks.","One way to calculate it is to take FCFF, subtract interest after tax and add net borrowing, meaning new debt raised minus debt repaid. For example, if FCFF is 16 million, after-tax interest is 3 million and the company repays a net 2 million of debt, FCFE is 11 million.","FCFE is used to value a company\'s shares directly. Because it belongs only to shareholders, it is discounted at the cost of equity rather than the weighted average cost of capital.","FCFE can swing from year to year when a company borrows or repays large amounts. A company could temporarily boost FCFE by borrowing heavily, so analysts look at trends over several years rather than a single figure."],"note":"Levered free cash flow means the same as FCFE. \\"Levered\\" means calculated after payments to lenders.","total":1500,"prev":{"slug":"free-cash-flow","term":"Free Cash Flow"},"next":{"slug":"free-cash-flow-to-firm","term":"Free Cash Flow to Firm (FCFF)"}}')}}]);